package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class WriteableCommandLineImpl_getValues_TriageGen1Test {

    private WriteableCommandLineImpl commandLine;
    private Option option1;
    private Option option2;

    @Before
    public void setUp() {
        option1 = new Option("opt1");
        option2 = new Option("opt2");

        commandLine = new WriteableCommandLineImpl(option1, new ArrayList<>());

        Map<Option, List> values = new HashMap<>();
        values.put(option1, Arrays.asList("value1"));
        values.put(option2, null);
        commandLine.setValues(values);

        Map<Option, List> defaultValues = new HashMap<>();
        defaultValues.put(option1, Arrays.asList("default1", "default2"));
        defaultValues.put(option2, Arrays.asList("default3"));
        commandLine.setDefaultValues(defaultValues);
    }

    @Test
    public void testGetValuesWithExistingOptionAndNonEmptyList() {
        List expected = Arrays.asList("value1");
        List actual = commandLine.getValues(option1, Collections.emptyList());
        assertEquals(expected, actual);
    }

    @Test
    public void testGetValuesWithExistingOptionAndEmptyList() {
        commandLine.setValues(new HashMap<>());
        List expected = Arrays.asList("default1", "default2");
        List actual = commandLine.getValues(option1, Collections.emptyList());
        assertEquals(expected, actual);
    }

    @Test
    public void testGetValuesWithExistingOptionAndNullList() {
        commandLine.setValues(new HashMap<>());
        List expected = Arrays.asList("default1", "default2");
        List actual = commandLine.getValues(option1, null);
        assertEquals(expected, actual);
    }

    @Test
    public void testGetValuesWithNonExistingOptionAndNonEmptyList() {
        List expected = Arrays.asList("default3");
        List actual = commandLine.getValues(option2, Collections.emptyList());
        assertEquals(expected, actual);
    }

    @Test
    public void testGetValuesWithNonExistingOptionAndEmptyList() {
        List expected = Arrays.asList("default3");
        List actual = commandLine.getValues(option2, Collections.emptyList());
        assertEquals(expected, actual);
    }

    @Test
    public void testGetValuesWithNonExistingOptionAndNullList() {
        List expected = Arrays.asList("default3");
        List actual = commandLine.getValues(option2, null);
        assertEquals(expected, actual);
    }

    @Test
    public void testGetValuesWithNonExistingOptionAndNullDefaultValues() {
        List actual = commandLine.getValues(option2, null);
        assertTrue(actual.isEmpty());
    }

    @Test
    public void testGetValuesWithExistingOptionAndNullDefaultValues() {
        commandLine.setValues(new HashMap<>());
        List actual = commandLine.getValues(option1, null);
        assertEquals(Arrays.asList("default1", "default2"), actual);
    }
}
